% Generated by scripts/research/build_action_grammar.py.
% Authored phrase, arc, and verdict-rule tables live in that builder; the
% factorizations and the verdicts below are derived from the two genres'
% transition tables and re-derived byte-for-byte by
% scripts/checks/action_grammar.py.
%
% WHAT THIS LAYER IS FOR. knowledge/strategies/action_vocabulary_map.pl
% compresses 644 bespoke action labels onto 119 canonical actions. This file
% is the level above: what shapes those actions make, and what a shape
% tells you about where a machine is going.
%
% THE COMPRESSION THAT MATTERS IS THE ARC. Projected to canonical actions,
% the 189 machines across both genres spell 187 distinct words -- almost no
% sharing. Projected to stance and run-length-collapsed, they spell 18
% arcs, and five of those are spelled by machines from both genres. An
% arithmetic strategy and a discursive practice never share an action; they
% share a normative arc. That is the level at which the two genres are
% commensurable, and it is a result of the projection rather than an
% assumption behind it.
%
% AN ARC IS NOT A CLAIM OF SAMENESS. Two machines with one arc agree on the
% order in which conservation and loss arrive and on nothing else. Reading
% more into a shared arc than that is the error this layer makes easy, so:
% strategies stay distinct, practices stay distinct, and a shared arc is a
% finding to report with both machines named.

:- module(action_grammar,
          [ action_phrase/3,
            normative_arc/3,
            machine_grammar/6,
            interruption_license/5
          ]).

% action_phrase(Name, sequence([Action, ...]), gloss(Text)).
action_phrase(accept_unchecked_then_skip, sequence([accept_without_check, omit_required_step]),
              gloss("Take a structure as usable without its check, then skip the step that check would have licensed.")).
action_phrase(accumulate_and_record_the_keeping, sequence([accumulate_total, record_conservation]),
              gloss("Accumulate the pieces and record that the whole was conserved.")).
action_phrase(acknowledge_twice_then_test, sequence([acknowledge_commitment, acknowledge_commitment, test_compatibility]),
              gloss("Put two commitments on one's own score, then test whether they can be held together.")).
action_phrase(attend_then_name_the_token, sequence([attend_to_utterance, name_the_incompatible_token]),
              gloss("Take the utterance up while it is still running, and name the word whose use here is what will not go through.")).
action_phrase(bind_the_roles, sequence([assign_roles, assign_roles]),
              gloss("Bind two givens to their roles in the relation before any of them is operated on. The corpus's most widely shared opening.")).
action_phrase(bind_then_collapse_the_roles, sequence([assign_roles, conflate_roles]),
              gloss("Bind the roles, then collapse two of them into one.")).
action_phrase(bind_then_compose, sequence([assign_roles, assign_roles, compose_expression]),
              gloss("Bind the roles, then assemble the expression the roles determine.")).
action_phrase(bring_both_to_a_common_unit, sequence([align_to_common_unit, align_to_common_unit]),
              gloss("Bring each of the two quantities into the shared unit in turn, so that neither is measured in the other's terms.")).
action_phrase(carry_forward_and_name, sequence([retain_unchanged, name_result]),
              gloss("Carry a quantity through untouched and name what it now stands for.")).
action_phrase(constitute_and_certify, sequence([unitize_referent, verify_invariant]),
              gloss("Constitute the whole, then certify the property the later comparison depends on.")).
action_phrase(constitute_and_partition, sequence([unitize_referent, partition_into_equal_parts]),
              gloss("Constitute the whole, then cut it into parts the strategy treats as equal. The opening the fraction and geometry measurement machines share.")).
action_phrase(count_and_name, sequence([count_units, name_result]),
              gloss("Count the units the iteration produced and name that count as the answer.")).
action_phrase(count_then_name_the_wrong_terminus, sequence([count_up_to_target, misname_result, record_loss]),
              gloss("Count forward to the target, then name the place reached instead of the distance travelled, or the reverse.")).
action_phrase(elaborate_then_deploy, sequence([elaborate_practice_algorithmically, deploy_vocabulary_from_practice]),
              gloss("Elaborate the practice from another by algorithm, then deploy the vocabulary that practice suffices for.")).
action_phrase(halt_and_record_the_loss, sequence([halt_before_completion, record_loss]),
              gloss("Stop a required traversal and record what stopping cost.")).
action_phrase(measure_together_then_order, sequence([align_to_common_unit, compare_magnitudes]),
              gloss("Bring both to a common unit, then decide the order relation.")).
action_phrase(misname_and_record_the_loss, sequence([misname_result, record_loss]),
              gloss("Name the wrong quantity, then record which relation went with it.")).
action_phrase(operate_and_record_the_keeping, sequence([combine_quantities, record_conservation]),
              gloss("Carry out the joining and record that the total was conserved.")).
action_phrase(order_and_release, sequence([compare_magnitudes, emit_result]),
              gloss("Decide the order and release it. The closing the comparison automata share.")).
action_phrase(partition_then_iterate, sequence([unitize_referent, partition_into_equal_parts, iterate_unit]),
              gloss("Constitute the whole, cut it into equal parts, then repeat one part. The fraction-scheme core in the Steffe/Olive/Hackenberg line.")).
action_phrase(read_the_givens_through, sequence([read_operand_attribute, read_operand_attribute]),
              gloss("Read two properties of the givens in succession, settling what the strategy is working with before it works.")).
action_phrase(read_then_set_aside_what_bears, sequence([read_operand_attribute, treat_relevant_as_irrelevant]),
              gloss("Read the property, then treat it as not bearing on what follows.")).
action_phrase(skip_then_misname, sequence([omit_required_step, misname_result]),
              gloss("Skip a step the strategy needs, then name a value that answers a different question. The corpus's most widely shared deformation.")).
action_phrase(skip_twice_then_misname, sequence([omit_required_step, omit_required_step, misname_result]),
              gloss("Skip two required steps in succession, then name what is left as the answer.")).
action_phrase(take_up_and_fix_the_unit, sequence([register_givens, select_unit_scale]),
              gloss("Hold the givens, then decide which unit or base the work will run in.")).
